// Author: MiYu. Native calls preserve session bindings and reject unsupported binary value categories.
#include "jass_binary_bridge.h"
#include <bit>
#include <stdexcept>

namespace war3 {
jass::Value toJass2Value(jass::Runtime& runtime,const JassBinaryProgram& program,jass::Id type,const JassBinaryNativeValue& arg){
    auto& module=runtime.module();auto category=module.type(type).category;if(arg.type==2 && !arg.bits && !arg.text && (category==jass::Category::String || category==jass::Category::Handle || category==jass::Category::Code))return {module.typeId("<null>"),0,{}};if(arg.type==4 && category==jass::Category::Integer)return runtime.integer(std::bit_cast<std::int32_t>(arg.bits));if(arg.type==5 && category==jass::Category::Real)return runtime.real(jass::Real::fromBits(arg.bits));if(arg.type==8 && category==jass::Category::Boolean && arg.bits<=1)return runtime.boolean(arg.bits!=0);if(arg.type==3 && category==jass::Category::Code){if(arg.bits && (arg.code.type!=type || arg.code.bits!=arg.bits || !arg.code.codeOwner))throw std::runtime_error("Invalid 2SAJ code argument");return arg.bits?arg.code:jass::Value{type,0,{}};}if(arg.type==7 && category==jass::Category::Handle)return runtime.handle(module.type(type).name,arg.bits);if(arg.type==6 && category==jass::Category::String){if(arg.text && arg.bits)throw std::runtime_error("Ambiguous 2SAJ string");if(arg.text)return runtime.string(*arg.text);if(!arg.bits)return {type,0,{}};if(arg.bits>program.symbols.size())throw std::runtime_error("Invalid 2SAJ string symbol");return runtime.string(program.symbols[arg.bits-1]);}throw std::runtime_error("Unsupported 2SAJ value type="+std::to_string(arg.type)+" expected="+module.type(type).name);
}
JassBinaryNativeValue fromJass2Value(const jass::Runtime& runtime,const jass::Value& value){switch(runtime.module().type(value.type).category){case jass::Category::Nothing:return {0,0,{}};case jass::Category::Integer:return {4,value.bits,{}};case jass::Category::Real:return {5,value.bits,{}};case jass::Category::String:return {6,0,value.text};case jass::Category::Handle:return {7,value.bits,{}};case jass::Category::Code:return {3,value.bits,{},value};case jass::Category::Boolean:return {8,value.bits,{}};default:throw std::runtime_error("Unsupported 2SAJ value result");}}
JassBinaryNativeValue invokeJass2Native(jass::Runtime& runtime,const JassBinaryProgram& program,const std::string& name,std::span<const JassBinaryNativeValue> arguments){
    auto& module=runtime.module();auto id=module.functionId(name);if(id==jass::none || !module.program().functions()[id].native)throw std::runtime_error("Unknown 2SAJ native: "+name);auto& signature=module.functions()[id];if(arguments.size()!=signature.parameters.size())throw std::runtime_error("2SAJ native argument count differs: "+name);std::vector<jass::Value> converted;converted.reserve(arguments.size());for(size_t i=0;i<arguments.size();++i)converted.push_back(toJass2Value(runtime,program,signature.parameters[i],arguments[i]));return fromJass2Value(runtime,runtime.invoke(name,converted));
}
}
